mapper.select:
SELECT representation_id AS representationId, snapshot_id AS snapshotId, representation_type AS representationType, content_type AS contentType, content_text AS contentText, structural_context AS structuralContext, target_type AS targetType, target_ref AS targetRef, canonical_evidence_id AS canonicalEvidenceId, container_ref AS containerRef, ordinal AS ordinal, facets_json AS facetsJson FROM asset_retrieval_units_v2 WHERE snapshot_id IN
#{sid}
AND canonical_evidence_id IN
#{cid}
AND returnable = TRUE ORDER BY canonical_evidence_id ASC, representation_id ASC

SELECT snapshot_id, node_type, ref, parent_ref, ordinal, title, level, block_type
FROM asset_structure_nodes
WHERE snapshot_id IN

    #{sid}

  AND ref IN

    #{r}

SELECT n.snapshot_id, n.ref, n.parent_ref, n.ordinal, n.block_type, s.raw_text, s.token_count, s.heading_chain_json FROM asset_structure_nodes n JOIN asset_raw_segments s ON s.snapshot_id = n.snapshot_id AND s.segment_index = n.ordinal WHERE n.node_type = 'segment' AND (
(n.snapshot_id = #{a.snapshotId} AND n.parent_ref = #{a.parentRef} AND n.ordinal BETWEEN #{a.centerOrdinal} - #{a.radius} AND #{a.centerOrdinal} + #{a.radius})
) ORDER BY n.snapshot_id ASC, n.parent_ref ASC, n.ordinal ASC

SELECT t.snapshot_id, t.ref, t.parent_ref, t.ordinal, t.block_type, t.raw_text, t.token_count, t.heading_chain_json FROM ( SELECT n.snapshot_id, n.ref, n.parent_ref, n.ordinal, n.block_type, s.raw_text, s.token_count, s.heading_chain_json, row_number() OVER (PARTITION BY n.snapshot_id, n.parent_ref ORDER BY n.ordinal) AS rn FROM asset_structure_nodes n JOIN asset_raw_segments s ON s.snapshot_id = n.snapshot_id AND s.segment_index = n.ordinal WHERE n.node_type = 'segment' AND n.snapshot_id IN
#{sid}
AND n.parent_ref IN
#{p}
) t WHERE t.rn <= #{maxRowsPerSection} ORDER BY t.snapshot_id ASC, t.parent_ref ASC, t.ordinal ASC

SELECT t.snapshot_id, t.ref, t.parent_ref, t.ordinal, t.block_type, t.raw_text, t.token_count, t.heading_chain_json FROM ( SELECT n.snapshot_id, n.ref, n.parent_ref, n.ordinal, n.block_type, s.raw_text, s.token_count, s.heading_chain_json, row_number() OVER (PARTITION BY n.snapshot_id ORDER BY n.ordinal) AS rn FROM asset_structure_nodes n JOIN asset_raw_segments s ON s.snapshot_id = n.snapshot_id AND s.segment_index = n.ordinal WHERE n.node_type = 'segment' AND n.snapshot_id IN
#{sid}
) t WHERE t.rn <= #{maxRowsPerDocument} ORDER BY t.snapshot_id ASC, t.ordinal ASC

SELECT snapshot_id AS snapshotId, SUM(COALESCE(token_count, 0)) AS totalTokens FROM asset_raw_segments WHERE snapshot_id IN
#{sid}
GROUP BY snapshot_id

SELECT snapshot_id, asset_ref, asset_type, table_ref, columns_json::text AS columns_json, row_count, readiness, schema_version FROM asset_structured_assets WHERE snapshot_id IN
#{sid}
AND table_ref IN
#{tr}

SELECT t.snapshot_id, t.table_ref, t.row_index, t.column_index, t.column_name, t.value, t.is_header FROM ( SELECT c.snapshot_id, c.table_ref, c.row_index, c.column_index, c.column_name, c.value, c.is_header, row_number() OVER (PARTITION BY c.snapshot_id, c.table_ref ORDER BY c.is_header DESC, c.row_index, c.column_index) AS rn FROM asset_table_cells c WHERE c.snapshot_id IN
#{sid}
AND c.table_ref IN
#{tr}
) t WHERE t.rn <= #{maxCellsPerTable} ORDER BY t.snapshot_id ASC, t.table_ref ASC, t.is_header DESC, t.row_index ASC, t.column_index ASC
